#include <iostream>
#include <thread>
using namespace std;

int a = 0;
int b = 0;

void first() {
    int s = 0;
    for (int i = 1; i <= 4; i++) s = s + i;
    a = s;
}

void second() {
    int s = 0;
    for (int i = 1; i <= 3; i++) s = s + i;
    b = s;
}

int main() {
    thread t1(first);
    thread t2(second);
    t1.join();
    t2.join();
    cout << "第一只 " << a << endl;
    cout << "第二只 " << b << endl;
    cout << "一共 " << a + b << endl;
    return 0;
}

#include <iostream>
#include <thread>
#include <mutex>
using namespace std;

int total = 0;
mutex mtx;

void addMany() {
    for (int i = 0; i < 200; i++) {
        lock_guard<mutex> guard(mtx);
        total = total + 1;
    }
}

int main() {
    thread t1(addMany);
    thread t2(addMany);
    thread t3(addMany);
    t1.join();
    t2.join();
    t3.join();
    cout << "一共 " << total << endl;
    return 0;
}
